import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"VMess Protocol","description":"","frontmatter":{},"headers":[],"relativePath":"en/development/protocols/vmess.md","filePath":"en/development/protocols/vmess.md","lastUpdated":1769207840000}`),a={name:`en/development/protocols/vmess.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="vmess-protocol" tabindex="-1">VMess Protocol <a class="header-anchor" href="#vmess-protocol" aria-label="Permalink to “VMess Protocol”">​</a></h1><p>VMess is an encrypted transport protocol that can act as a bridge between Xray clients and servers.</p><h2 id="version" tabindex="-1">Version <a class="header-anchor" href="#version" aria-label="Permalink to “Version”">​</a></h2><p>The current version number is 1.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to “Dependencies”">​</a></h2><h3 id="underlying-protocol" tabindex="-1">Underlying Protocol <a class="header-anchor" href="#underlying-protocol" aria-label="Permalink to “Underlying Protocol”">​</a></h3><p>VMess is a TCP-based protocol; all data is transmitted using TCP.</p><h3 id="user-id" tabindex="-1">User ID <a class="header-anchor" href="#user-id" aria-label="Permalink to “User ID”">​</a></h3><p>The ID is equivalent to a <a href="https://en.wikipedia.org/wiki/Universally_unique_identifier" target="_blank" rel="noreferrer">UUID</a>. It is a 16-byte random number that acts as a token. An ID looks like: <code>de305d54-75b4-431b-adb2-eb6b9e546014</code>. It is almost completely random and can be generated using any UUID generator, such as <a href="https://www.uuidgenerator.net/" target="_blank" rel="noreferrer">this one</a>.</p><p>The User ID can be specified in the <a href="./../../config/">configuration file</a>.</p><h3 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to “Functions”">​</a></h3><ul><li>MD5: <a href="https://en.wikipedia.org/wiki/MD5" target="_blank" rel="noreferrer">MD5 Function</a><ul><li>Input parameter: Byte array of arbitrary length</li><li>Output: A 16-byte array</li></ul></li><li>HMAC: <a href="https://en.wikipedia.org/wiki/Hash-based_message_authentication_code" target="_blank" rel="noreferrer">HMAC Function</a><ul><li>Input parameters: <ul><li>H: Hash function</li><li>K: Key, byte array of arbitrary length</li><li>M: Message, byte array of arbitrary length</li></ul></li></ul></li><li>Shake: <a href="https://en.wikipedia.org/wiki/SHA-3" target="_blank" rel="noreferrer">SHA3-Shake128 Function</a><ul><li>Input parameter: String of arbitrary length</li><li>Output: String of arbitrary length</li></ul></li></ul><h2 id="communication-process" tabindex="-1">Communication Process <a class="header-anchor" href="#communication-process" aria-label="Permalink to “Communication Process”">​</a></h2><p>VMess is a stateless protocol, meaning no handshake is required between the client and server to transmit data. Each data transmission has no effect on previous or subsequent transmissions.</p><p>The VMess client initiates a request. The server determines if the request comes from a legitimate client. If verification passes, the request is forwarded, and the received response is sent back to the client.</p><p>VMess uses an asymmetric format, meaning the request sent by the client and the response from the server use different formats.</p><h2 id="client-request" tabindex="-1">Client Request <a class="header-anchor" href="#client-request" aria-label="Permalink to “Client Request”">​</a></h2><table tabindex="0"><thead><tr><th>16 bytes</th><th>X bytes</th><th>Remaining part</th></tr></thead><tbody><tr><td>Authentication Info</td><td>Command Section</td><td>Data Section</td></tr></tbody></table><h3 id="authentication-info" tabindex="-1">Authentication Info <a class="header-anchor" href="#authentication-info" aria-label="Permalink to “Authentication Info”">​</a></h3><p>The authentication info is a 16-byte hash value, calculated as follows:</p><ul><li>H = MD5</li><li>K = User ID (16 bytes)</li><li>M = UTC time, precise to seconds, a random value within 30 seconds before or after the current time (8 bytes, Big Endian)</li><li>Hash = HMAC(H, K, M)</li></ul><h3 id="command-section" tabindex="-1">Command Section <a class="header-anchor" href="#command-section" aria-label="Permalink to “Command Section”">​</a></h3><p>The command section is encrypted using AES-128-CFB:</p><ul><li>Key: MD5(User ID + []byte(&#39;c48619fe-8f02-49e0-b9e9-edf763e17e21&#39;))</li><li>IV: MD5(X + X + X + X), where X = []byte(Time used for generating authentication info) (8 bytes, Big Endian)</li></ul><table tabindex="0"><thead><tr><th style="text-align:center;">1 byte</th><th style="text-align:center;">16 bytes</th><th style="text-align:center;">16 bytes</th><th style="text-align:center;">1 byte</th><th style="text-align:center;">1 byte</th><th style="text-align:center;">4 bits</th><th style="text-align:center;">4 bits</th><th style="text-align:center;">1 byte</th><th style="text-align:center;">1 byte</th><th style="text-align:center;">2 bytes</th><th style="text-align:center;">1 byte</th><th style="text-align:center;">N bytes</th><th style="text-align:center;">P bytes</th><th style="text-align:center;">4 bytes</th></tr></thead><tbody><tr><td style="text-align:center;">Version Ver</td><td style="text-align:center;">Data Encryption IV</td><td style="text-align:center;">Data Encryption Key</td><td style="text-align:center;">Response Auth V</td><td style="text-align:center;">Option Opt</td><td style="text-align:center;">Margin P</td><td style="text-align:center;">Encryption Sec</td><td style="text-align:center;">Reserved</td><td style="text-align:center;">Command Cmd</td><td style="text-align:center;">Port</td><td style="text-align:center;">Address Type T</td><td style="text-align:center;">Address A</td><td style="text-align:center;">Random Value</td><td style="text-align:center;">Checksum F</td></tr></tbody></table><p>Option Opt details: (When a bit is 1, the option is enabled)</p><table tabindex="0"><thead><tr><th style="text-align:center;">0</th><th style="text-align:center;">1</th><th style="text-align:center;">2</th><th style="text-align:center;">3</th><th style="text-align:center;">4</th><th style="text-align:center;">5</th><th style="text-align:center;">6</th><th style="text-align:center;">7</th></tr></thead><tbody><tr><td style="text-align:center;">X</td><td style="text-align:center;">X</td><td style="text-align:center;">X</td><td style="text-align:center;">X</td><td style="text-align:center;">X</td><td style="text-align:center;">M</td><td style="text-align:center;">R</td><td style="text-align:center;">S</td></tr></tbody></table><p>Where:</p><ul><li><strong>Version Ver</strong>: Always 1.</li><li><strong>Data Encryption IV</strong>: Random value.</li><li><strong>Data Encryption Key</strong>: Random value.</li><li><strong>Response Auth V</strong>: Random value.</li><li><strong>Option Opt</strong>: <ul><li>S (0x01): Standard format data stream (Recommended enabled).</li><li>R (0x02): Client expects to reuse TCP connection (Deprecated in Xray 2.23+). <ul><li>Valid only when S is enabled.</li></ul></li><li>M (0x04): Enable metadata obfuscation (Recommended enabled). <ul><li>Valid only when S is enabled.</li><li>When enabled, both client and server need to construct two Shake instances respectively: RequestMask = Shake(Request Data IV), ResponseMask = Shake(Response Data IV).</li></ul></li><li>X: Reserved.</li></ul></li><li><strong>Margin P</strong>: Adds P bytes of random value before the checksum.</li><li><strong>Encryption Sec</strong>: Specifies the encryption method for the data section. Options: <ul><li>0x00: AES-128-CFB</li><li>0x01: No encryption</li><li>0x02: AES-128-GCM</li><li>0x03: ChaCha20-Poly1305</li></ul></li><li><strong>Command Cmd</strong>: <ul><li>0x01: TCP data</li><li>0x02: UDP data</li></ul></li><li><strong>Port</strong>: Integer port number in Big Endian format.</li><li><strong>Address Type T</strong>: <ul><li>0x01: IPv4</li><li>0x02: Domain name</li><li>0x03: IPv6</li></ul></li><li><strong>Address A</strong>: <ul><li>When T = 0x01, A is a 4-byte IPv4 address.</li><li>When T = 0x02, A is 1-byte length (L) + L bytes domain name.</li><li>When T = 0x03, A is a 16-byte IPv6 address.</li></ul></li><li><strong>Checksum F</strong>: FNV1a hash of all content in the command section except F.</li></ul><h3 id="data-section" tabindex="-1">Data Section <a class="header-anchor" href="#data-section" aria-label="Permalink to “Data Section”">​</a></h3><p>When Opt(S) is enabled, the data section uses this format. The actual request data is split into several small chunks, each formatted as follows. The server verifies all small chunks before forwarding them according to the basic format.</p><table tabindex="0"><thead><tr><th style="text-align:center;">2 bytes</th><th style="text-align:center;">L bytes</th></tr></thead><tbody><tr><td style="text-align:center;">Length L</td><td style="text-align:center;">Data Packet</td></tr></tbody></table><p>Where:</p><ul><li><strong>Length L</strong>: Integer in Big Endian format, maximum value is 2^14. <ul><li>When Opt(M) is enabled, Value of L = Real Value xor Mask. Mask = (RequestMask.NextByte() &lt;&lt; 8) + RequestMask.NextByte().</li></ul></li><li><strong>Data Packet</strong>: Data packet encrypted by the specified encryption method.</li></ul><p>Before transmission ends, the data packet must contain actual data (data other than length and authentication data). When transmission ends, the client must send an empty data packet, i.e., L = 0 (no encryption) or length of authentication data (with encryption), to indicate the end of transmission.</p><p>Depending on the encryption method, the data packet format is as follows:</p><ul><li><strong>No encryption</strong>: <ul><li>L bytes: Actual data.</li></ul></li><li><strong>AES-128-CFB</strong>: The entire data section is encrypted using AES-128-CFB. <ul><li>4 bytes: FNV1a hash of actual data.</li><li>L - 4 bytes: Actual data.</li></ul></li><li><strong>AES-128-GCM</strong>: Key is the Key from the Command Section, IV = count (2 bytes) + IV (10 bytes). count starts from 0 and increments by 1 for each packet; IV is the 3rd to 12th bytes of the Command Section IV. <ul><li>L - 16 bytes: Actual data.</li><li>16 bytes: GCM authentication info.</li></ul></li><li><strong>ChaCha20-Poly1305</strong>: Key = MD5(Command Section Key) + MD5(MD5(Command Section Key)), IV = count (2 bytes) + IV (10 bytes). count starts from 0 and increments by 1 for each packet; IV is the 3rd to 12th bytes of the Command Section IV. <ul><li>L - 16 bytes: Actual data.</li><li>16 bytes: Poly1305 authentication info.</li></ul></li></ul><h2 id="server-response" tabindex="-1">Server Response <a class="header-anchor" href="#server-response" aria-label="Permalink to “Server Response”">​</a></h2><p>The response header data is encrypted using AES-128-CFB, with IV being MD5(Data Encryption IV) and Key being MD5(Data Encryption Key). The actual response data varies depending on encryption settings.</p><table tabindex="0"><thead><tr><th style="text-align:left;">1 byte</th><th style="text-align:left;">1 byte</th><th style="text-align:left;">1 byte</th><th style="text-align:left;">1 byte</th><th style="text-align:left;">M bytes</th><th style="text-align:left;">Remaining part</th></tr></thead><tbody><tr><td style="text-align:left;">Response Auth V</td><td style="text-align:left;">Option Opt</td><td style="text-align:left;">Command Cmd</td><td style="text-align:left;">Command Length M</td><td style="text-align:left;">Command Content</td><td style="text-align:left;">Actual Response Data</td></tr></tbody></table><p>Where:</p><ul><li><strong>Response Auth V</strong>: Must match the Response Auth V in the client request.</li><li><strong>Option Opt</strong>: <ul><li>0x01: Server is ready to reuse TCP connection (Deprecated in Xray 2.23+).</li></ul></li><li><strong>Command Cmd</strong>: <ul><li>0x01: Dynamic port command.</li></ul></li><li><strong>Actual Response Data</strong>: <ul><li>If Opt(S) in the request was enabled, standard format is used; otherwise, basic format is used.</li><li>The format is the same as the request data. <ul><li>When Opt(M) is enabled, Value of Length L = Real Value xor Mask. Mask = (ResponseMask.NextByte() &lt;&lt; 8) + ResponseMask.NextByte().</li></ul></li></ul></li></ul><h3 id="dynamic-port-command" tabindex="-1">Dynamic Port Command <a class="header-anchor" href="#dynamic-port-command" aria-label="Permalink to “Dynamic Port Command”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">1 byte</th><th style="text-align:left;">2 bytes</th><th style="text-align:left;">16 bytes</th><th style="text-align:left;">2 bytes</th><th style="text-align:left;">1 byte</th><th style="text-align:left;">1 byte</th></tr></thead><tbody><tr><td style="text-align:left;">Reserved</td><td style="text-align:left;">Port</td><td style="text-align:left;">User ID</td><td style="text-align:left;">AlterID</td><td style="text-align:left;">User Level</td><td style="text-align:left;">Validity Time T</td></tr></tbody></table><p>Where:</p><ul><li><strong>Port</strong>: Integer port number in Big Endian format.</li><li><strong>Validity Time T</strong>: Number of minutes.</li></ul><p>When the client receives a dynamic port command, the server has opened a new port for communication, and the client can send data to the new port. After T minutes, this port will expire, and the client must resume using the main port for communication.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li>To ensure forward compatibility, the values of all reserved fields must be 0.</li></ul>`,49)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};